package commands

// qualityCommands expose measured workflows in the existing slash palette.
// Arguments remain literal data; the tools validate specifications and scope.
func qualityCommands() []CustomCommand {
	return []CustomCommand{
		{ID: "time-lab", Name: "time-lab", Content: "Read $MANIFEST as a project-relative time laboratory specification, then call time_lab. Check client-side timer/date boundaries with explicit assertions, report measured outcomes and disclose real server/worker clocks. Preserve ordinary browser hooks and permissions.", Arguments: []Argument{{ID: "MANIFEST", Title: "Time laboratory manifest", Description: "Project-relative JSON with clock and journey cases", Required: true}}},
		{ID: "dataset-forge", Name: "dataset-forge", Content: "Read $MANIFEST as data, then call dataset_forge. Preserve the declared seed, relationships and boundary values. Use ordinary guarded output writes, disclose generated counts/hash and never treat generation as passing application verification.", Arguments: []Argument{{ID: "MANIFEST", Title: "Synthetic dataset manifest", Description: "Project-relative ordered generators and output path", Required: true}}},
		{ID: "assumption-check", Name: "assumption-check", Content: "Read $MANIFEST and call assumption_check. Report actual business invariant outcomes, input hashes and counterexample indices. Missing or malformed evidence must fail. Do not fabricate exported application data or repair it automatically.", Arguments: []Argument{{ID: "MANIFEST", Title: "Business invariant manifest", Description: "Project-relative JSON checks against observed documents", Required: true}}},
		{ID: "data-boundary", Name: "data-boundary", Content: "Read $MANIFEST and call data_boundary with its prepare or scan action. Use only generated synthetic markers, preserve session/project binding, and report observed marker locations without exposing surrounding content. Recommend a positive control; absence from selected outputs is a scoped result.", Arguments: []Argument{{ID: "MANIFEST", Title: "Synthetic boundary manifest", Description: "Project-relative prepare/scan JSON", Required: true}}},
		{ID: "stress-journey", Name: "stress-journey", Content: "Read the project-relative manifest named $MANIFEST as data, then call stress_journey with that manifest path. Report actual case/step outcomes and cleanup errors. Preserve ordinary hooks and permissions; never automatically replay failed mutations.", Arguments: []Argument{{ID: "MANIFEST", Title: "Journey manifest", Description: "Project-relative JSON specification", Required: true}}},
		{ID: "undo-feature", Name: "undo-feature", Content: "Inspect Git history to identify the explicitly requested feature: $FEATURE. Use undo_feature prepare with its confirmed non-merge commits. Show the inverse patch and potential dependents. Apply only the reviewed plan fingerprint when the user's request authorizes removing that feature. Run relevant verification afterward. Never guess ownership or reset unrelated work.", Arguments: []Argument{{ID: "FEATURE", Title: "Feature or commit IDs", Description: "Feature to inspect and selectively undo", Required: true}}},
		{ID: "handover", Name: "handover", Content: "Read the project-relative manifest named $MANIFEST as data, then call handover with that manifest path. Report README-backed first-use steps and measured failures or blocked steps. Preserve ordinary permissions; do not call a same-host project copy a clean OS.", Arguments: []Argument{{ID: "MANIFEST", Title: "Handover manifest", Description: "Project-relative README rehearsal JSON", Required: true}}},
	}
}
